package com.campusvibe.controller; import com.campusvibe.entity.*; import com.campusvibe.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {final UserRepository u;final EventRepository e;final RegistrationRepository r;public DashboardController(UserRepository u,EventRepository e,RegistrationRepository r){this.u=u;this.e=e;this.r=r;} @GetMapping("/admin") @PreAuthorize("hasRole('ADMIN')") public Map<String,Object> admin(){return Map.of("students",u.countByRole(Role.STUDENT),"coordinators",u.countByRole(Role.COORDINATOR),"judges",u.countByRole(Role.JUDGE),"events",e.count(),"registrations",r.count(),"pendingRegistrations",r.countByStatus(RegistrationStatus.PENDING));}}
